bool areAlmostEqual(char* s1, char* s2) {
    int n = strlen(s1);
    int i1 = -1;
    int i2 = -1;
    for (int i = 0; i < n; i++) {
        if (s1[i] != s2[i]) {
            if (i1 == -1) {
                i1 = i;
            } else if (i2 == -1) {
                i2 = i;
            } else {
                return 0;
            }
        }
    }
    if (i1 == -1 && i2 == -1) {
        return 1;
    }
    if (i1 == -1 || i2 == -1) {
        return 0;
    }
    return s1[i1] == s2[i2] && s1[i2] == s2[i1];
}

package io.github.leetcode.strings;

public class CheckIfOneStringSwapCanMakeStringsEqual {

    public boolean areAlmostEqual(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;
        }

        if (s1.equals(s2)) {
            return true;
        }

        int n = s1.length();
        int diff = 0;
        char c1 = '.', c2 = '.';
        char d1 = '.', d2 = '.';

        for (int i = 0; i < n; i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                diff++;
                if (diff == 1) {
                    c1 = s1.charAt(i);
                    c2 = s2.charAt(i);
                } else if (diff == 2) {
                    d1 = s1.charAt(i);
                    d2 = s2.charAt(i);
                } else {
                    return false;
                }
            }
        }

        return (c1 == d2) && (c2 == d1);
    }

}

